{
  "explanation": "When you scale a triangle by a factor k, every linear length—including its base and height—is multiplied by k. Area equals ½ × base × height, so the new area becomes ½ × (k·base) × (k·height) = k² times the original area. The same k² rule holds for any 2D shape because area is a product of two lengths.",
  "manimCode": "const sc = 0.7;
const baseVerts = [
  [-2 * sc, -1.2 * sc, 0],
  [2.5 * sc, -1.2 * sc, 0],
  [-0.5 * sc, 2 * sc, 0]
];

const origTri = new Polygon({ vertices: baseVerts, color: BLUE });
origTri.setFill(BLUE, 0.35);
origTri.setStrokeWidth(3);

let k = 1.5;
function scaledVerts(factor) {
  return baseVerts.map(v => [v[0] * factor, v[1] * factor, 0]);
}

let scaledTri = new Polygon({ vertices: scaledVerts(k), color: YELLOW });
scaledTri.setFill(YELLOW, 0.3);
scaledTri.setStrokeWidth(3);

const title = new Text({ text: 'Area scales by k²', color: WHITE, fontSize: 32 });
title.moveTo([0, 3.3, 0]);

let formula = new MathTex({ latex: `\\tfrac{1}{2}(kb)(kh) = k^{2}\\cdot\\tfrac{1}{2}bh` });
await formula.waitForRender();
formula.moveTo([0, -3.2, 0]);

let kLabel = new Text({ text: `k = ${k.toFixed(2)}   →   area factor = ${(k * k).toFixed(2)}`, color: WHITE, fontSize: 26 });
kLabel.moveTo([0, -2.5, 0]);

scene.add(origTri, scaledTri, title, formula, kLabel);

const controls = new Controls(scene, { position: 'top-right', width: 260 });
controls.addSlider({
  label: 'Scale factor k',
  min: 0.4,
  max: 2.2,
  value: k,
  step: 0.05,
  onChange: (val) => {
    k = val;
    scaledTri.setVertices(scaledVerts(k));
    const pos = kLabel.getCenter();
    scene.remove(kLabel);
    kLabel = new Text({
      text: `k = ${k.toFixed(2)}   →   area factor = ${(k * k).toFixed(2)}`,
      color: WHITE,
      fontSize: 26
    });
    kLabel.moveTo(pos);
    scene.add(kLabel);
  }
});

controls.addButton({
  label: 'Reset k = 1',
  onClick: () => {
    k = 1;
    scaledTri.setVertices(scaledVerts(k));
    const pos = kLabel.getCenter();
    scene.remove(kLabel);
    kLabel = new Text({
      text: `k = ${k.toFixed(2)}   →   area factor = ${(k * k).toFixed(2)}`,
      color: WHITE,
      fontSize: 26
    });
    kLabel.moveTo(pos);
    scene.add(kLabel);
  }
});

await scene.wait(999999);"
}

